(function(){
  // Capacitor exposes plugins on window.Capacitor.Plugins
  const cap = window.Capacitor;
  if (!cap) return {ok:false, err:'no-Capacitor'};
  const ks = cap.Plugins?.AiStreamKeepalive;
  if (!ks) return {ok:false, err:'no-AiStreamKeepalive-plugin', plugins: Object.keys(cap.Plugins || {})};
  return ks.start({activeCount: 1, text: 'AI 任务进行中（test from CDP）'}).then(r => ({ok:true, result:r})).catch(e => ({ok:false, err:String(e)}));
})()
